package utils

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// expandBraces expands {a,b} alternatives in a pattern into multiple patterns.
func expandBraces(pattern string) []string {
	depth := 0
	start := -1
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		if c == '\\' && i+1 < len(pattern) {
			i++
			continue
		}
		if c == '{' {
			if depth == 0 {
				start = i
			}
			depth++
		} else if c == '}' && depth > 0 {
			depth--
			if depth == 0 {
				inner := pattern[start+1 : i]
				// split inner by top level commas
				var parts []string
				d := 0
				last := 0
				for j := 0; j < len(inner); j++ {
					switch inner[j] {
					case '{':
						d++
					case '}':
						d--
					case ',':
						if d == 0 {
							parts = append(parts, inner[last:j])
							last = j + 1
						}
					}
				}
				parts = append(parts, inner[last:])
				var result []string
				for _, p := range parts {
					for _, e := range expandBraces(pattern[:start] + p + pattern[i+1:]) {
						result = append(result, e)
					}
				}
				return result
			}
		}
	}
	return []string{pattern}
}

// matchSegment matches a single path segment against a glob segment supporting
// '*', '?' and character classes.
func matchSegment(pattern, name string) bool {
	p := []rune(pattern)
	n := []rune(name)
	return matchRunes(p, n)
}

func matchRunes(p, n []rune) bool {
	for len(p) > 0 {
		switch p[0] {
		case '*':
			// collapse consecutive stars
			for len(p) > 0 && p[0] == '*' {
				p = p[1:]
			}
			if len(p) == 0 {
				return true
			}
			for i := 0; i <= len(n); i++ {
				if matchRunes(p, n[i:]) {
					return true
				}
			}
			return false
		case '?':
			if len(n) == 0 {
				return false
			}
			p = p[1:]
			n = n[1:]
		case '[':
			if len(n) == 0 {
				return false
			}
			end := -1
			for i := 1; i < len(p); i++ {
				if p[i] == ']' && i > 1 {
					end = i
					break
				}
			}
			if end == -1 {
				// treat '[' literally
				if n[0] != '[' {
					return false
				}
				p = p[1:]
				n = n[1:]
				continue
			}
			class := p[1:end]
			negate := false
			if len(class) > 0 && (class[0] == '!' || class[0] == '^') {
				negate = true
				class = class[1:]
			}
			matched := false
			for i := 0; i < len(class); i++ {
				if i+2 < len(class) && class[i+1] == '-' {
					if n[0] >= class[i] && n[0] <= class[i+2] {
						matched = true
					}
					i += 2
				} else if class[i] == n[0] {
					matched = true
				}
			}
			if matched == negate {
				return false
			}
			p = p[end+1:]
			n = n[1:]
		case '\\':
			if len(p) > 1 {
				p = p[1:]
			}
			if len(n) == 0 || n[0] != p[0] {
				return false
			}
			p = p[1:]
			n = n[1:]
		default:
			if len(n) == 0 || n[0] != p[0] {
				return false
			}
			p = p[1:]
			n = n[1:]
		}
	}
	return len(n) == 0
}

func splitPath(p string) []string {
	parts := strings.Split(p, "/")
	var result []string
	for _, part := range parts {
		if part != "" {
			result = append(result, part)
		}
	}
	return result
}

func matchSegments(pattern, name []string) bool {
	for len(pattern) > 0 {
		if pattern[0] == "**" {
			for len(pattern) > 0 && pattern[0] == "**" {
				pattern = pattern[1:]
			}
			if len(pattern) == 0 {
				return true
			}
			for i := 0; i <= len(name); i++ {
				if matchSegments(pattern, name[i:]) {
					return true
				}
			}
			return false
		}
		if len(name) == 0 {
			return false
		}
		if !matchSegment(pattern[0], name[0]) {
			return false
		}
		pattern = pattern[1:]
		name = name[1:]
	}
	return len(name) == 0
}

// GlobMatch checks whether the given path matches the glob pattern. Both are
// expected to be absolute (or both relative) slash separated paths.
func GlobMatch(pattern, path string) bool {
	for _, p := range expandBraces(pattern) {
		if matchSegments(splitPath(p), splitPath(path)) {
			return true
		}
	}
	return false
}

func hasGlobMeta(s string) bool {
	return strings.ContainsAny(s, "*?[{")
}

// Glob returns the files/dirs in the filesystem matching the given pattern.
// The pattern can be relative to the current working directory or absolute.
func Glob(pattern string) ([]string, error) {
	abs := pattern
	if !filepath.IsAbs(abs) {
		cwd, err := os.Getwd()
		if err != nil {
			return nil, err
		}
		abs = filepath.Join(cwd, abs)
	}
	if strings.HasSuffix(pattern, "/") {
		return nil, nil
	}
	var results []string
	seen := map[string]bool{}
	for _, p := range expandBraces(abs) {
		if !hasGlobMeta(p) {
			p = filepath.Clean(p)
			if _, err := os.Lstat(p); err == nil {
				if !seen[p] {
					seen[p] = true
					results = append(results, p)
				}
			}
			continue
		}
		segs := splitPath(p)
		globWalk("/", segs, func(match string) {
			if !seen[match] {
				seen[match] = true
				results = append(results, match)
			}
		})
	}
	return results, nil
}

func globWalk(dir string, segs []string, emit func(string)) {
	if len(segs) == 0 {
		emit(dir)
		return
	}
	seg := segs[0]
	rest := segs[1:]
	if seg == "**" {
		// zero segments
		globWalk(dir, rest, emit)
		entries, err := os.ReadDir(dir)
		if err != nil {
			return
		}
		names := make([]string, 0, len(entries))
		for _, e := range entries {
			names = append(names, e.Name())
		}
		sort.Strings(names)
		for _, name := range names {
			full := filepath.Join(dir, name)
			info, err := os.Stat(full)
			if err != nil || !info.IsDir() {
				continue
			}
			globWalk(full, segs, emit)
		}
		return
	}
	if !hasGlobMeta(seg) {
		full := filepath.Join(dir, seg)
		if _, err := os.Lstat(full); err != nil {
			return
		}
		if len(rest) > 0 {
			info, err := os.Stat(full)
			if err != nil || !info.IsDir() {
				return
			}
		}
		globWalk(full, rest, emit)
		return
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		names = append(names, e.Name())
	}
	sort.Strings(names)
	for _, name := range names {
		if !matchSegment(seg, name) {
			continue
		}
		full := filepath.Join(dir, name)
		if len(rest) > 0 {
			info, err := os.Stat(full)
			if err != nil || !info.IsDir() {
				continue
			}
		}
		globWalk(full, rest, emit)
	}
}
