package utils

import (
	"fmt"
	"io"
	"math"
	"os"
	"strings"
	"time"
	"unicode/utf8"
)

var spinnerChars = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}

// Progress mimics a spinner style progress bar rendered on stderr.
type Progress struct {
	w            io.Writer
	start        time.Time
	count        int
	description  string
	maxLineWidth int
	finished     bool
}

func NewProgress() *Progress {
	p := &Progress{w: os.Stderr, start: time.Now()}
	// render the blank state (does not account for the line width).
	str := p.render()
	_, _ = io.WriteString(p.w, str)
	return p
}

func (p *Progress) spinner() string {
	idx := int(math.Round(math.Mod(float64(time.Since(p.start).Milliseconds()/100), float64(len(spinnerChars)))))
	if idx < 0 || idx >= len(spinnerChars) {
		idx = 0
	}
	return spinnerChars[idx]
}

func (p *Progress) rate() string {
	elapsed := time.Since(p.start).Seconds()
	var r float64
	if elapsed > 0 {
		r = float64(p.count) / elapsed
	}
	if r > 1 {
		return fmt.Sprintf("%0.0f it/s", r)
	} else if r*60 > 1 {
		return fmt.Sprintf("%0.0f it/min", r*60)
	}
	return fmt.Sprintf("%0.0f it/hr", r*3600)
}

func (p *Progress) render() string {
	elapsed := (time.Duration(time.Since(p.start).Seconds()) * time.Second).String()
	return fmt.Sprintf("\r%s %s (%s) [%s] ", p.spinner(), p.description, p.rate(), elapsed)
}

func (p *Progress) clear() {
	if p.maxLineWidth == 0 {
		return
	}
	_, _ = io.WriteString(p.w, fmt.Sprintf("\r%s\r", strings.Repeat(" ", p.maxLineWidth)))
}

func (p *Progress) draw() {
	if p.finished {
		return
	}
	p.clear()
	str := p.render()
	w := utf8.RuneCountInString(strings.ReplaceAll(str, "\r", ""))
	if w > p.maxLineWidth {
		p.maxLineWidth = w
	}
	_, _ = io.WriteString(p.w, str)
}

func (p *Progress) Add(n int) {
	p.count += n
	p.draw()
}

func (p *Progress) Describe(d string) {
	p.description = d
	p.draw()
}

func (p *Progress) Finish() {
	if p.finished {
		return
	}
	p.clear()
	str := p.render()
	_, _ = io.WriteString(p.w, str)
	_, _ = io.WriteString(p.w, "\n")
	p.finished = true
}
