package config

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"

	"dep-tree/internal/check"
	"dep-tree/internal/js"
	"dep-tree/internal/python"
	"dep-tree/internal/rust"
	"dep-tree/internal/utils"
)

const DefaultConfigPath = ".dep-tree.yml"

type Config struct {
	Path          string        `yaml:"-"`
	Exclude       []string      `yaml:"exclude"`
	Only          []string      `yaml:"only"`
	UnwrapExports bool          `yaml:"unwrapExports"`
	Check         check.Config  `yaml:"check"`
	Js            js.Config     `yaml:"js"`
	Python        python.Config `yaml:"python"`
	Rust          rust.Config   `yaml:"rust"`
}

func NewConfig() *Config {
	cwd, _ := os.Getwd()
	return &Config{
		Path:  cwd,
		Check: check.Config{Path: cwd},
	}
}

var ErrNotFound = errors.New("config file not found")

// ParseConfig loads the config from the given path. If the path is empty, the
// default .dep-tree.yml is loaded, and if it is not present a default config is returned.
func ParseConfig(cfgPath string) (*Config, error) {
	if cfgPath == "" {
		if !utils.FileExists(DefaultConfigPath) {
			cfg := NewConfig()
			return cfg, ErrNotFound
		}
		cfgPath = DefaultConfigPath
	}
	content, err := os.ReadFile(cfgPath)
	if err != nil {
		return nil, err
	}
	absPath := utils.AbsPath(cfgPath)
	cfg := Config{}
	decoder := yaml.NewDecoder(bytesReader(content))
	decoder.KnownFields(true)
	if err := decoder.Decode(&cfg); err != nil {
		if errors.Is(err, errEOF) {
			// empty file
		} else {
			return nil, fmt.Errorf(`config file "%s" is not a valid yml file: %w`, cfgPath, err)
		}
	}
	dir := filepath.Dir(absPath)
	cfg.Path = dir
	cfg.Check.Path = dir
	// make the patterns absolute, relative to the config file dir.
	for i, p := range cfg.Exclude {
		cfg.Exclude[i] = absPattern(dir, p)
	}
	for i, p := range cfg.Only {
		cfg.Only[i] = absPattern(dir, p)
	}
	return &cfg, nil
}

func absPattern(dir, p string) string {
	if filepath.IsAbs(p) {
		return filepath.Clean(p)
	}
	return filepath.Join(dir, p)
}

// AbsPatternFromCwd makes a pattern absolute relative to the current working dir.
func AbsPatternFromCwd(p string) string {
	cwd, _ := os.Getwd()
	return absPattern(cwd, p)
}

// IgnoreFiles decides whether a file is ignored by the exclude/only configuration.
