package js

import (
	"unicode"
)

type tokenKind int

const (
	tkIdent tokenKind = iota
	tkString
	tkTemplate
	tkNumber
	tkPunct
)

type token struct {
	kind tokenKind
	text string // for strings, the unquoted content
}

func isIdentStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r)
}

func isIdentPart(r rune) bool {
	return isIdentStart(r) || unicode.IsDigit(r)
}

// lex tokenizes JavaScript/TypeScript source code in a lenient way. Comments
// and whitespace are discarded, strings spanning multiple lines are allowed,
// and unknown characters are emitted as punctuation.
func lex(src []rune) []token {
	var tokens []token
	i := 0
	n := len(src)
	for i < n {
		c := src[i]
		// whitespace
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' || unicode.IsSpace(c) {
			i++
			continue
		}
		// line comment
		if c == '/' && i+1 < n && src[i+1] == '/' {
			for i < n && src[i] != '\n' {
				i++
			}
			continue
		}
		// block comment (must be closed)
		if c == '/' && i+1 < n && src[i+1] == '*' {
			end := -1
			for j := i + 2; j+1 < n; j++ {
				if src[j] == '*' && src[j+1] == '/' {
					end = j + 2
					break
				}
			}
			if end != -1 {
				i = end
				continue
			}
		}
		// strings
		if c == '\'' || c == '"' || c == '`' {
			end := -1
			for j := i + 1; j < n; j++ {
				if src[j] == '\\' {
					j++
					continue
				}
				if src[j] == c {
					end = j
					break
				}
			}
			if end != -1 {
				kind := tkString
				if c == '`' {
					kind = tkTemplate
				}
				tokens = append(tokens, token{kind: kind, text: string(src[i+1 : end])})
				i = end + 1
				continue
			}
			tokens = append(tokens, token{kind: tkPunct, text: string(c)})
			i++
			continue
		}
		if isIdentStart(c) {
			j := i + 1
			for j < n && isIdentPart(src[j]) {
				j++
			}
			tokens = append(tokens, token{kind: tkIdent, text: string(src[i:j])})
			i = j
			continue
		}
		if unicode.IsDigit(c) {
			j := i + 1
			for j < n && (isIdentPart(src[j]) || src[j] == '.') {
				j++
			}
			tokens = append(tokens, token{kind: tkNumber, text: string(src[i:j])})
			i = j
			continue
		}
		tokens = append(tokens, token{kind: tkPunct, text: string(c)})
		i++
	}
	return tokens
}
