	// From is the module the symbol is re-exported from, empty for local exports.
	From string
	// All is set for `export * from 'x'` statements.
	All bool
}

type fileStatements struct {
	Imports []importStatement
	Exports []exportName
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek(off int) *token {
	if p.pos+off < len(p.toks) {
		return &p.toks[p.pos+off]
	}
	return nil
}

func (p *parser) isIdent(off int, text string) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkIdent && t.text == text
}

func (p *parser) isPunct(off int, text string) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkPunct && t.text == text
}

func (p *parser) isAnyIdent(off int) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkIdent
}

func (p *parser) isString(off int) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkString
}

// parseNamedList parses `{ item ("," item?)* }` where item is
// `"type"? Ident ("as" Ident)?` (allowType) or `Ident ("as" Ident)?`.
// It returns the local names (after `as`), the original names and ok.
func (p *parser) parseNamedList(allowType bool) (names []string, originals []string, ok bool) {
	save := p.pos
	if !p.isPunct(0, "{") {
		return nil, nil, false
	}
	p.pos++
	parseItem := func() bool {
		if allowType && p.isIdent(0, "type") {
			p.pos++
		}
		if !p.isAnyIdent(0) {
			return false
		}
		orig := p.peek(0).text
		name := orig
		p.pos++
		if p.isIdent(0, "as") {
			p.pos++
			if !p.isAnyIdent(0) {
				return false
			}
			name = p.peek(0).text
			p.pos++
		}
		names = append(names, name)
		originals = append(originals, orig)
		return true
	}
	if !parseItem() {
		p.pos = save
		return nil, nil, false
	}
	for p.isPunct(0, ",") {
		p.pos++
		if p.isPunct(0, ",") || p.isPunct(0, "}") {
			continue
		}
		if !parseItem() {
			p.pos = save
			return nil, nil, false
		}
	}
	if !p.isPunct(0, "}") {
		p.pos = save
		return nil, nil, false
	}
	p.pos++
	return names, originals, true
}

// parseImport parses an import statement starting at the current position
// (which must be the `import` keyword).
func (p *parser) parseImport() (string, bool) {
	save := p.pos
	p.pos++ // import
	if p.isIdent(0, "type") {
		p.pos++
	}
	if p.isString(0) {
		s := p.peek(0).text
		p.pos++
		return s, true
	}
	fail := func() (string, bool) {
		p.pos = save
		return "", false
	}
	if p.isPunct(0, "{") {
		if _, _, ok := p.parseNamedList(true); !ok {
			return fail()
		}
	} else if p.isPunct(0, "*") {
		p.pos++
		if p.isIdent(0, "as") {
			p.pos++
			if !p.isAnyIdent(0) {
				return fail()
			}
			p.pos++
		}
	} else {
		if p.isAnyIdent(0) {
			p.pos++
		}
		if p.isPunct(0, ",") {
			p.pos++
			if p.isPunct(0, "{") {
				if _, _, ok := p.parseNamedList(true); !ok {
					return fail()
				}
			} else if p.isPunct(0, "*") {
				p.pos++
				if p.isIdent(0, "as") {
					p.pos++
					if !p.isAnyIdent(0) {
						return fail()
					}
					p.pos++
				}
			}
		}
	}
	if !p.isIdent(0, "from") {
		return fail()
	}
	p.pos++
	if !p.isString(0) {
		return fail()
	}
	s := p.peek(0).text
	p.pos++
	return s, true
}

// parseCall parses `( String )` at the current position.
func (p *parser) parseCall() (string, bool) {
	if p.isPunct(0, "(") && p.isString(1) && p.isPunct(2, ")") {
		s := p.peek(1).text
		p.pos += 3
		return s, true
	}
	return "", false
}

// parseExport parses an export statement starting at the `export` keyword.
func (p *parser) parseExport() ([]exportName, bool) {
	save := p.pos
	p.pos++ // export
	fail := func() ([]exportName, bool) {
		p.pos = save
		return nil, false
	}
	if p.isIdent(0, "default") {
		p.pos++
		return []exportName{{Name: "default"}}, true
	}
	if p.isPunct(0, "*") {
		p.pos++
		alias := ""
		if p.isIdent(0, "as") {
			p.pos++
			if !p.isAnyIdent(0) {
				return fail()
			}
			alias = p.peek(0).text
			p.pos++
		}
		if !p.isIdent(0, "from") || !p.isString(1) {
			return fail()
		}
		from := p.peek(1).text
		p.pos += 2
		if alias != "" {
			return []exportName{{Name: alias, From: from}}, true
		}
		return []exportName{{All: true, From: from}}, true
	}
	if p.isPunct(0, "{") {
		names, _, ok := p.parseNamedList(false)
		if !ok {
			return fail()
		}
		from := ""
		if p.isIdent(0, "from") && p.isString(1) {
			from = p.peek(1).text
			p.pos += 2
		}
		var result []exportName
		for _, n := range names {
			result = append(result, exportName{Name: n, From: from})
		}
		return result, true
	}
	if p.isIdent(0, "const") || p.isIdent(0, "let") || p.isIdent(0, "var") ||
		p.isIdent(0, "class") || p.isIdent(0, "type") || p.isIdent(0, "interface") ||
		p.isIdent(0, "enum") {
		p.pos++
		if !p.isAnyIdent(0) {
			return fail()
		}
		name := p.peek(0).text
		p.pos++
		return []exportName{{Name: name}}, true
	}
	if p.isIdent(0, "async") {
		p.pos++
	}
	if p.isIdent(0, "function") {
		p.pos++
		if p.isPunct(0, "*") {
			p.pos++
		}
		if !p.isAnyIdent(0) {
			return fail()
		}
		name := p.peek(0).text
		p.pos++
		return []exportName{{Name: name}}, true
	}
	return fail()
}

// parseStatements extracts imports and exports from the token stream.
func parseStatements(toks []token) *fileStatements {
	p := &parser{toks: toks}
	result := &fileStatements{}
	for p.pos < len(p.toks) {
		t := p.toks[p.pos]
		if t.kind == tkIdent {
			switch t.text {
			case "import":
				if path, ok := p.parseImport(); ok {
					result.Imports = append(result.Imports, importStatement{Path: path})
					continue
				}
				p.pos++
				if path, ok := p.parseCall(); ok {
					result.Imports = append(result.Imports, importStatement{Path: path})
				}
				continue
			case "require":
				p.pos++
				if path, ok := p.parseCall(); ok {
					result.Imports = append(result.Imports, importStatement{Path: path})
				}
				continue
			case "export":
				if exports, ok := p.parseExport(); ok {
					result.Exports = append(result.Exports, exports...)
					continue
				}
				p.pos++
				continue
			}
		}
		p.pos++
	}
	return result
}
