package js

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"dep-tree/internal/language"
	"dep-tree/internal/utils"
)

var Extensions = []string{"js", "jsx", "ts", "tsx", "mjs", "cjs", "mts", "cts"}

// resolution extensions, in order of priority.
var resolveExtensions = []string{"js", "ts", "tsx", "jsx", "d.ts", "mjs", "cjs"}

type Language struct {
	pkgCache  map[string]*packageJson
	tsCache   map[string]*tsConfig
	wsCache   map[string]*workspaces
	fileCache map[string]*parsedFile
}

func NewLanguage() *Language {
	return &Language{
		pkgCache:  map[string]*packageJson{},
		tsCache:   map[string]*tsConfig{},
		wsCache:   map[string]*workspaces{},
		fileCache: map[string]*parsedFile{},
	}
}

type parsedFile struct {
	path       string
	statements *fileStatements
	loc        int
	// exports is an ordered map of exported names to the file where they are
	// exported from.
	exportNames []string
	exportPaths map[string]string
	exportsDone bool
	exportsBusy bool
}

func (l *Language) parse(path string) (*parsedFile, error) {
	if f, ok := l.fileCache[path]; ok {
		return f, nil
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	f := &parsedFile{
		path:        path,
		statements:  parseStatements(lex([]rune(string(content)))),
		loc:         utils.CountLines(content),
		exportPaths: map[string]string{},
	}
	l.fileCache[path] = f
	return f, nil
}

func (f *parsedFile) addExport(name, path string) {
	if _, ok := f.exportPaths[name]; !ok {
		f.exportNames = append(f.exportNames, name)
	}
	f.exportPaths[name] = path
}

// exports computes the exported names of a file, resolving `export *` statements.
func (l *Language) exports(f *parsedFile) {
	if f.exportsDone || f.exportsBusy {
		return
	}
	f.exportsBusy = true
	for _, e := range f.statements.Exports {
		if e.From == "" {
			f.addExport(e.Name, f.path)
			continue
		}
		resolved, err := l.resolveImport(f.path, e.From)
		if err != nil || resolved == "" {
			continue
		}
		if e.All {
			other, err := l.parse(resolved)
			if err != nil {
				continue
			}
			l.exports(other)
			for _, name := range other.exportNames {
				f.addExport(name, resolved)
			}
			continue
		}
		f.addExport(e.Name, resolved)
	}
	f.exportsBusy = false
	f.exportsDone = true
}

func (l *Language) ParseFile(path string) (*language.FileInfo, error) {
	f, err := l.parse(path)
	if err != nil {
		return nil, err
	}
	info := &language.FileInfo{AbsPath: path, Loc: f.loc}
	seen := map[string]bool{}
	add := func(p string) {
		if p == "" || seen[p] {
			return
		}
		seen[p] = true
		info.Deps = append(info.Deps, p)
	}
	for _, imp := range f.statements.Imports {
		resolved, err := l.resolveImport(path, imp.Path)
		if err != nil {
			info.Errors = append(info.Errors, err)
			continue
		}
		add(resolved)
	}
	l.exports(f)
	for _, name := range f.exportNames {
		add(f.exportPaths[name])
	}
	// self imports are not dependencies
	var deps []string
	for _, d := range info.Deps {
		if d != path {
			deps = append(deps, d)
		}
	}
	info.Deps = deps
	return info, nil
}

