}

func isRelative(p string) bool {
	return strings.HasPrefix(p, "./") || strings.HasPrefix(p, "..")
}

func (l *Language) resolveImport(from string, importPath string) (string, error) {
	if importPath == "" {
		return "", fmt.Errorf("import path cannot be empty")
	}
	if len(importPath) < 2 {
		return "", fmt.Errorf("invalid import path %s", importPath)
	}
	dir := filepath.Dir(from)
	if isRelative(importPath) {
		abs := filepath.Join(dir, importPath)
		if resolved := l.resolvePath(abs); resolved != "" {
			return resolved, nil
		}
		return "", fmt.Errorf("could not perform relative import for '%s' because the file or dir was not found", importPath)
	}
