	if pkg := l.findPackageRoot(dir); pkg != nil {
		pkgDir := filepath.Dir(pkg.absPath)
		if ts := l.readTsConfig(pkgDir); ts != nil {
			baseDir := pkgDir
			if ts.CompilerOptions.BaseUrl != "" {
				baseDir = filepath.Join(pkgDir, ts.CompilerOptions.BaseUrl)
				if resolved := l.resolvePath(filepath.Join(baseDir, importPath)); resolved != "" {
					return resolved, nil
				}
			}
			var candidates []string
			for pattern, targets := range ts.CompilerOptions.Paths {
				prefix := strings.TrimSuffix(pattern, "*")
				if !strings.HasPrefix(importPath, prefix) {
					continue
				}
				for _, target := range targets {
					replaced := strings.ReplaceAll(importPath, prefix, strings.TrimSuffix(target, "*"))
					candidate := filepath.Join(baseDir, replaced)
					if resolved := l.resolvePath(candidate); resolved != "" {
						return resolved, nil
					}
					candidates = append(candidates, candidate)
				}
			}
			if len(candidates) > 0 {
				return "", fmt.Errorf("import '%s' was matched to path '%s' in tscofing's paths option, but the resolved path did not match an existing file", importPath, strings.Join(candidates, "', '"))
			}
		}
	}
