{"command":"cd /workspace && cat > internal/python/parser.go <<'EOF'
package python

import (
	"strings"
	"unicode"
)

type tokKind int

const (
	tkIdent tokKind = iota
	tkPunct
	tkString
	tkNumber
	tkNewline
)

type token struct {
	kind tokKind
	text string
}

func isIdentStart(r rune) bool {
	return r == '_' || unicode.IsLetter(r)
}

func isIdentPart(r rune) bool {
	return isIdentStart(r) || unicode.IsDigit(r)
}

func isStringPrefix(s string) bool {
	if len(s) == 0 || len(s) > 3 {
		return false
	}
	for _, c := range strings.ToLower(s) {
		if c != 'r' && c != 'b' && c != 'u' && c != 'f' {
			return false
		}
	}
	return true
}

// lex tokenizes python source code leniently.
func lex(src []rune) []token {
	var tokens []token
	n := len(src)
	i := 0
	depth := 0
	for i < n {
		c := src[i]
		if c == '\n' {
			if depth == 0 {
				tokens = append(tokens, token{kind: tkNewline})
			}
			i++
			continue
		}
		if c == '\\' && i+1 < n && src[i+1] == '\n' {
			i += 2
			continue
		}
		if c == '\\' && i+2 < n && src[i+1] == '\r' && src[i+2] == '\n' {
			i += 3
			continue
		}
		if unicode.IsSpace(c) {
			i++
			continue
		}
		if c == '#' {
			for i < n && src[i] != '\n' {
				i++
			}
			continue
		}
		if c == '\'' || c == '"' {
			i = lexString(src, i, &tokens)
			continue
		}
		if isIdentStart(c) {
			j := i + 1
			for j < n && isIdentPart(src[j]) {
				j++
			}
			word := string(src[i:j])
			if j < n && (src[j] == '\'' || src[j] == '"') && isStringPrefix(word) {
				i = lexString(src, j, &tokens)
				continue
			}
			tokens = append(tokens, token{kind: tkIdent, text: word})
			i = j
			continue
		}
		if unicode.IsDigit(c) {
			j := i + 1
			for j < n && (isIdentPart(src[j]) || src[j] == '.') {
				j++
			}
			tokens = append(tokens, token{kind: tkNumber, text: string(src[i:j])})
			i = j
			continue
		}
		switch c {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		}
		tokens = append(tokens, token{kind: tkPunct, text: string(c)})
		i++
	}
	tokens = append(tokens, token{kind: tkNewline})
	return tokens
}

func lexString(src []rune, i int, tokens *[]token) int {
	n := len(src)
	q := src[i]
	triple := i+2 < n && src[i+1] == q && src[i+2] == q
	if triple {
		j := i + 3
		for j < n {
			if src[j] == '\\' {
				j += 2
				continue
			}
			if src[j] == q && j+2 < n && src[j+1] == q && src[j+2] == q {
				*tokens = append(*tokens, token{kind: tkString, text: string(src[i+3 : j])})
				return j + 3
			}
			j++
		}
		*tokens = append(*tokens, token{kind: tkString, text: string(src[i+3:])})
		return n
	}
	j := i + 1
	for j < n {
		if src[j] == '\\' {
			j += 2
			continue
		}
		if src[j] == q {
			*tokens = append(*tokens, token{kind: tkString, text: string(src[i+1 : j])})
			return j + 1
		}
		if src[j] == '\n' {
			break
		}
		j++
	}
	// unterminated string: treat the quote as punctuation.
	*tokens = append(*tokens, token{kind: tkPunct, text: string(q)})
	return i + 1
}

// importStatement represents either `import a.b` (Relative == 0, From empty)
// or `from ..a.b import c, d`.
type importStatement struct {
	// Dots is the number of leading dots in a relative `from` import.
	Dots int
	// Path is the dotted module path split in parts.
	Path []string
	// Names are the imported names (nil for plain `import` statements).
	Names []string
	// All is set for `from x import *`.
	All bool
	// IsFrom is true for `from ... import ...` statements.
	IsFrom bool
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek() *token {
	if p.pos < len(p.toks) {
		return &p.toks[p.pos]
	}
	return nil
}

func (p *parser) isIdent(text string) bool {
	t := p.peek()
	return t != nil && t.kind == tkIdent && t.text == text
}

func (p *parser) isPunct(text string) bool {
	t := p.peek()
	return t != nil && t.kind == tkPunct && t.text == text
}

func (p *parser) atEnd() bool {
	t := p.peek()
	return t == nil || t.kind == tkNewline || (t.kind == tkPunct && t.text == ";")
}

// skipStatement advances to the next statement.
func (p *parser) skipStatement() {
	for !p.atEnd() {
		p.pos++
	}
	if p.pos < len(p.toks) {
		p.pos++
	}
}

// parseDotted parses `a.b.c`.
func (p *parser) parseDotted() []string {
	var parts []string
	t := p.peek()
	if t == nil || t.kind != tkIdent {
		return nil
	}
	parts = append(parts, t.text)
	p.pos++
	for p.isPunct(".") {
		p.pos++
		t := p.peek()
		if t == nil || t.kind != tkIdent {
			return nil
		}
		parts = append(parts, t.text)
		p.pos++
	}
	return parts
}

func parseImports(toks []token) []importStatement {
	p := &parser{toks: toks}
	var result []importStatement
	for p.pos < len(p.toks) {
		if p.isIdent("import") {
			p.pos++
			for {
				parts := p.parseDotted()
				if parts == nil {
					break
				}
				result = append(result, importStatement{Path: parts})
				if p.isIdent("as") {
					p.pos++
					if t := p.peek(); t != nil && t.kind == tkIdent {
						p.pos++
					}
				}
				if p.isPunct(",") {
					p.pos++
					continue
				}
				break
			}
			p.skipStatement()
			continue
		}
		if p.isIdent("from") {
			p.pos++
			stmt := importStatement{IsFrom: true}
			for p.isPunct(".") {
				stmt.Dots++
				p.pos++
			}
			if t := p.peek(); t != nil && t.kind == tkIdent && t.text != "import" {
				parts := p.parseDotted()
				if parts == nil {
					p.skipStatement()
					continue
				}
				stmt.Path = parts
			}
			if stmt.Dots == 0 && len(stmt.Path) == 0 {
				p.skipStatement()
				continue
			}
			if !p.isIdent("import") {
				p.skipStatement()
				continue
			}
			p.pos++
			if p.isPunct("*") {
				stmt.All = true
				p.pos++
			} else {
				paren := false
				if p.isPunct("(") {
					paren = true
					p.pos++
				}
				for {
					t := p.peek()
					if t == nil {
						break
					}
					if paren && t.kind == tkPunct && t.text == ")" {
						break
					}
					if !paren && p.atEnd() {
						break
					}
					if t.kind == tkIdent {
						if t.text == "as" {
							p.pos++
							if t2 := p.peek(); t2 != nil && t2.kind == tkIdent {
								p.pos++
							}
							continue
						}
						stmt.Names = append(stmt.Names, t.text)
						p.pos++
						continue
					}
					if t.kind == tkPunct && t.text == "," {
						p.pos++
						continue
					}
					if t.kind == tkNewline {
						p.pos++
						continue
					}
					break
				}
			}
			if stmt.All || len(stmt.Names) > 0 {
				result = append(result, stmt)
			}
			p.skipStatement()
			continue
		}
		p.skipStatement()
	}
	return result
}
EOF
echo ok"}

