type Language struct {
	rootCache map[string]string
}

func NewLanguage() *Language {
	return &Language{rootCache: map[string]string{}}
}

// findRoot returns the closest ancestor dir (starting at dir) that contains a
// python project marker file, or "" if none.
func (l *Language) findRoot(dir string) string {
	if r, ok := l.rootCache[dir]; ok {
		return r
	}
	r := utils.FindClosestDirWithFile(dir, rootMarkers...)
	l.rootCache[dir] = r
	return r
}

func (l *Language) Display(path string) language.DisplayResult {
	root := l.findRoot(filepath.Dir(path))
	if root == "" {
		return language.DisplayResult{}
	}
	rel, err := filepath.Rel(root, path)
	if err != nil {
		return language.DisplayResult{}
	}
	return language.DisplayResult{Name: rel}
}

func (l *Language) searchDirs(fileDir string) []string {
	dirs := []string{fileDir}
	if root := l.findRoot(fileDir); root != "" && root != fileDir {
		dirs = append(dirs, root)
	}
	return dirs
}

// resolveDotted tries to resolve a dotted module path inside dir. It returns the
// path to the module file, or the module directory, and whether anything was found.
func resolveDotted(dir string, parts []string) (file string, moduleDir string, found bool) {
	p := filepath.Join(append([]string{dir}, parts...)...)
	if utils.FileExists(p + ".py") {
		return p + ".py", "", true
	}
	if utils.DirExists(p) {
		return "", p, true
	}
	return "", "", false
}

func (l *Language) ParseFile(path string) (*language.FileInfo, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	info := &language.FileInfo{AbsPath: path, Loc: utils.CountLines(content)}
	statements := parseImports(lex([]rune(string(content))))
	fileDir := filepath.Dir(path)
	seen := map[string]bool{}
	add := func(p string) {
		if p == "" || p == path || seen[p] {
			return
		}
		seen[p] = true
		info.Deps = append(info.Deps, p)
	}
	for _, stmt := range statements {
		if !stmt.IsFrom {
			for _, dir := range l.searchDirs(fileDir) {
				file, moduleDir, found := resolveDotted(dir, stmt.Path)
				if !found {
					continue
				}
				if file != "" {
					add(file)
				} else if init := filepath.Join(moduleDir, "__init__.py"); utils.FileExists(init) {
					add(init)
				}
				break
			}
			continue
		}
		var file, moduleDir string
		if stmt.Dots > 0 {
			base := fileDir
			for i := 1; i < stmt.Dots; i++ {
				base = filepath.Dir(base)
			}
			target := filepath.Join(append([]string{base}, stmt.Path...)...)
			if utils.DirExists(target) {
				moduleDir = target
			} else if utils.FileExists(target + ".py") {
				file = target + ".py"
			} else {
				info.Errors = append(info.Errors, fmt.Errorf("could not resolve relative import from %s to %s", fileDir, target))
				continue
			}
		} else {
			found := false
			for _, dir := range l.searchDirs(fileDir) {
				f, d, ok := resolveDotted(dir, stmt.Path)
				if ok {
					file, moduleDir, found = f, d, true
					break
				}
			}
			if !found {
				continue
			}
		}
		if file != "" {
			add(file)
			continue
		}
		if stmt.All {
			if init := filepath.Join(moduleDir, "__init__.py"); utils.FileExists(init) {
				add(init)
			}
			continue
		}
		resolvedAny := false
		var unresolved []string
		for _, name := range stmt.Names {
			candidate := filepath.Join(moduleDir, name+".py")
			if utils.FileExists(candidate) {
				add(candidate)
				resolvedAny = true
			} else {
				unresolved = append(unresolved, name)
			}
		}
		if len(unresolved) > 0 {
			init := filepath.Join(moduleDir, "__init__.py")
			if utils.FileExists(init) {
				add(init)
			} else if !resolvedAny {
				info.Errors = append(info.Errors, fmt.Errorf("cannot import file %s.py from directory %s", unresolved[0], moduleDir))
			}
		}
	}
	return info, nil
}

func init() {
	_ = strings.TrimSpace
}
