cd /workspace && cat > internal/rust/lexer.go <<'EOF'
package rust

import "unicode"

type tokKind int

const (
	tkIdent tokKind = iota
	tkPunct
	tkString
	tkNumber
)

type token struct {
	kind tokKind
	text string
}

func isIdentStart(r rune) bool {
	return r == '_' || unicode.IsLetter(r)
}

func isIdentPart(r rune) bool {
	return isIdentStart(r) || unicode.IsDigit(r)
}

// lex tokenizes rust source code leniently.
func lex(src []rune) []token {
	var tokens []token
	n := len(src)
	i := 0
	for i < n {
		c := src[i]
		if unicode.IsSpace(c) {
			i++
			continue
		}
		if c == '/' && i+1 < n && src[i+1] == '/' {
			for i < n && src[i] != '\n' {
				i++
			}
			continue
		}
		if c == '/' && i+1 < n && src[i+1] == '*' {
			depth := 1
			j := i + 2
			for j < n && depth > 0 {
				if j+1 < n && src[j] == '/' && src[j+1] == '*' {
					depth++
					j += 2
					continue
				}
				if j+1 < n && src[j] == '*' && src[j+1] == '/' {
					depth--
					j += 2
					continue
				}
				j++
			}
			i = j
			continue
		}
		// raw strings: r"..." r#"..."# br"..." etc
		if (c == 'r' || c == 'b') && i+1 < n {
			j := i
			if src[j] == 'b' {
				j++
			}
			if j < n && src[j] == 'r' {
				k := j + 1
				hashes := 0
				for k < n && src[k] == '#' {
					hashes++
					k++
				}
				if k < n && src[k] == '"' {
					// find closing quote followed by `hashes` hashes
					m := k + 1
					closed := false
					for m < n {
						if src[m] == '"' {
							cnt := 0
							for m+1+cnt < n && cnt < hashes && src[m+1+cnt] == '#' {
								cnt++
							}
							if cnt == hashes {
								tokens = append(tokens, token{kind: tkString, text: string(src[k+1 : m])})
								i = m + 1 + hashes
								closed = true
								break
							}
						}
						m++
					}
					if closed {
						continue
					}
				}
			}
			if src[i] == 'b' && i+1 < n && (src[i+1] == '"' || src[i+1] == '\'') {
				i++
				c = src[i]
			}
		}
		if c == '"' {
			j := i + 1
			for j < n {
				if src[j] == '\\' {
					j += 2
					continue
				}
				if src[j] == '"' {
					break
				}
				j++
			}
			if j < n {
				tokens = append(tokens, token{kind: tkString, text: string(src[i+1 : j])})
				i = j + 1
			} else {
				tokens = append(tokens, token{kind: tkPunct, text: "\""})
				i++
			}
			continue
		}
		if c == '\'' {
			// char literal or lifetime
			if i+2 < n && src[i+1] == '\\' {
				j := i + 2
				for j < n && src[j] != '\'' && src[j] != '\n' {
					j++
				}
				if j < n && src[j] == '\'' {
					tokens = append(tokens, token{kind: tkString, text: string(src[i+1 : j])})
					i = j + 1
					continue
				}
			} else if i+2 < n && src[i+2] == '\'' {
				tokens = append(tokens, token{kind: tkString, text: string(src[i+1 : i+2])})
				i += 3
				continue
			}
			// lifetime: skip the quote and the identifier
			i++
			for i < n && isIdentPart(src[i]) {
				i++
			}
			continue
		}
		if isIdentStart(c) {
			j := i + 1
			for j < n && isIdentPart(src[j]) {
				j++
			}
			word := string(src[i:j])
			if word == "r" && j < n && src[j] == '#' && j+1 < n && isIdentStart(src[j+1]) {
				k := j + 1
				for k < n && isIdentPart(src[k]) {
					k++
				}
				tokens = append(tokens, token{kind: tkIdent, text: string(src[j+1 : k])})
				i = k
				continue
			}
			tokens = append(tokens, token{kind: tkIdent, text: word})
			i = j
			continue
		}
		if unicode.IsDigit(c) {
			j := i + 1
			for j < n && (isIdentPart(src[j]) || src[j] == '.') {
				j++
			}
			tokens = append(tokens, token{kind: tkNumber, text: string(src[i:j])})
			i = j
			continue
		}
		if c == ':' && i+1 < n && src[i+1] == ':' {
			tokens = append(tokens, token{kind: tkPunct, text: "::"})
			i += 2
			continue
		}
		tokens = append(tokens, token{kind: tkPunct, text: string(c)})
		i++
	}
	return tokens
}
EOF
cat > internal/rust/parser.go <<'EOF'
package rust

// statement is either a `mod x;` declaration or a flattened `use` path.
type statement struct {
	Mod string   // for `mod x;`
	Use []string // for use paths, e.g. ["crate", "a", "b"] or ["self", "x", "*"]
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek(off int) *token {
	if p.pos+off < len(p.toks) {
		return &p.toks[p.pos+off]
	}
	return nil
}

func (p *parser) isIdent(off int, text string) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkIdent && t.text == text
}

func (p *parser) isAnyIdent(off int) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkIdent
}

func (p *parser) isPunct(off int, text string) bool {
	t := p.peek(off)
	return t != nil && t.kind == tkPunct && t.text == text
}

// parseUseTree parses a use tree and returns all the flattened paths.
func (p *parser) parseUseTree(prefix []string) ([][]string, bool) {
	if p.isPunct(0, "*") {
		p.pos++
		path := append(append([]string{}, prefix...), "*")
		return [][]string{path}, true
	}
	if p.isPunct(0, "{") {
		p.pos++
		var result [][]string
		for !p.isPunct(0, "}") {
			if p.peek(0) == nil {
				return nil, false
			}
			paths, ok := p.parseUseTree(prefix)
			if !ok {
				return nil, false
			}
			result = append(result, paths...)
			if p.isPunct(0, ",") {
				p.pos++
				continue
			}
			if !p.isPunct(0, "}") {
				return nil, false
			}
		}
		p.pos++
		return result, true
	}
	if !p.isAnyIdent(0) {
		return nil, false
	}
	path := append([]string{}, prefix...)
	path = append(path, p.peek(0).text)
	p.pos++
	for p.isPunct(0, "::") {
		p.pos++
		if p.isPunct(0, "{") || p.isPunct(0, "*") {
			return p.parseUseTree(path)
		}
		if !p.isAnyIdent(0) {
			return nil, false
		}
		path = append(path, p.peek(0).text)
		p.pos++
	}
	if p.isIdent(0, "as") {
		p.pos++
		if p.isAnyIdent(0) || p.isPunct(0, "_") {
			p.pos++
		} else {
			return nil, false
		}
	}
	return [][]string{path}, true
}

func parseStatements(toks []token) []statement {
	p := &parser{toks: toks}
	var result []statement
	for p.pos < len(p.toks) {
		if p.isIdent(0, "mod") && p.isAnyIdent(1) && p.isPunct(2, ";") {
			result = append(result, statement{Mod: p.peek(1).text})
			p.pos += 3
			continue
		}
		if p.isIdent(0, "use") {
			save := p.pos
			p.pos++
			if p.isPunct(0, "::") {
				p.pos++
			}
			paths, ok := p.parseUseTree(nil)
			if ok {
				for _, path := range paths {
					result = append(result, statement{Use: path})
				}
				continue
			}
			p.pos = save + 1
			continue
		}
		p.pos++
	}
	return result
}
EOF
