package rust

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/BurntSushi/toml"

	"dep-tree/internal/language"
	"dep-tree/internal/utils"
)

var Extensions = []string{"rs"}

type cargoToml struct {
	Package struct {
		Name string `toml:"name"`
	} `toml:"package"`
}

type modNode struct {
	file     string
	parent   *modNode
	children map[string]*modNode
}

type crate struct {
	dir     string
	name    string
	root    *modNode
	rootErr error
	// byFile maps absolute file paths to their node in the mod tree.
	byFile map[string]*modNode
}

type Language struct {
	crates    map[string]*crate
	dirCache  map[string]string
	fileCache map[string][]statement
}

func NewLanguage() *Language {
	return &Language{
		crates:    map[string]*crate{},
		dirCache:  map[string]string{},
		fileCache: map[string][]statement{},
	}
}

func (l *Language) cargoDir(dir string) string {
	if d, ok := l.dirCache[dir]; ok {
		return d
	}
	d := utils.FindClosestDirWithFile(dir, "Cargo.toml")
	l.dirCache[dir] = d
	return d
}

func (l *Language) statements(path string) ([]statement, error) {
	if s, ok := l.fileCache[path]; ok {
		return s, nil
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	s := parseStatements(lex([]rune(string(content))))
	l.fileCache[path] = s
	return s, nil
}

// resolveMod resolves `mod name;` declared in file.
func resolveMod(file string, name string) string {
	dir := filepath.Dir(file)
	if p := filepath.Join(dir, name+".rs"); utils.FileExists(p) {
		return p
	}
	if p := filepath.Join(dir, name, "mod.rs"); utils.FileExists(p) {
		return p
	}
	return ""
}

func (l *Language) buildTree(node *modNode, c *crate, visited map[string]bool) error {
	if visited[node.file] {
		return nil
	}
	visited[node.file] = true
	c.byFile[node.file] = node
	stmts, err := l.statements(node.file)
	if err != nil {
		return err
	}
	for _, s := range stmts {
		if s.Mod == "" {
			continue
		}
		if _, exists := node.children[s.Mod]; exists {
			continue
		}
		resolved := resolveMod(node.file, s.Mod)
		if resolved == "" {
			return fmt.Errorf("could not find mod \"%s\" in path \"%s\"", s.Mod, filepath.Dir(node.file))
		}
		child := &modNode{file: resolved, parent: node, children: map[string]*modNode{}}
		node.children[s.Mod] = child
		if err := l.buildTree(child, c, visited); err != nil {
			return err
		}
	}
	return nil
}

func (l *Language) getCrate(dir string) *crate {
	cargo := l.cargoDir(dir)
	if cargo == "" {
		return nil
	}
	if c, ok := l.crates[cargo]; ok {
		return c
	}
	c := &crate{dir: cargo, byFile: map[string]*modNode{}}
	var ct cargoToml
	if content, err := os.ReadFile(filepath.Join(cargo, "Cargo.toml")); err == nil {
		if err := toml.Unmarshal(content, &ct); err == nil {
			c.name = ct.Package.Name
		}
	}
	rootFile := ""
	for _, candidate := range []string{"src/lib.rs", "src/main.rs"} {
		p := filepath.Join(cargo, candidate)
		if utils.FileExists(p) {
			rootFile = p
			break
		}
	}
	if rootFile == "" {
		c.rootErr = fmt.Errorf("main executable/library Rust file not found for cargo workspace in %s", cargo)
	} else {
		c.root = &modNode{file: rootFile, children: map[string]*modNode{}}
		if err := l.buildTree(c.root, c, map[string]bool{}); err != nil {
			c.root = nil
			c.rootErr = err
		}
	}
	l.crates[cargo] = c
	return c
}

func (l *Language) Display(path string) language.DisplayResult {
	c := l.getCrate(filepath.Dir(path))
	if c == nil {
		return language.DisplayResult{}
	}
	rel, err := filepath.Rel(c.dir, path)
	if err != nil {
		return language.DisplayResult{Group: c.name}
	}
	return language.DisplayResult{Name: rel, Group: c.name}
}

var errModChain = fmt.Errorf("could not find mod chain  in the projects mod tree")

func (l *Language) resolveUse(c *crate, path string, segs []string) (string, error) {
	if len(segs) == 0 {
		return "", nil
	}
	first := segs[0]
	if first != "crate" && first != "self" && first != "super" {
		// bare path: resolve against the mods declared in this file.
		stmts, _ := l.statements(path)
		for _, s := range stmts {
			if s.Mod != "" && s.Mod == first {
				if resolved := resolveMod(path, first); resolved != "" {
					return resolved, nil
				}
				return "", nil
			}
		}
		return "", nil
	}
	if c.root == nil {
		return "", c.rootErr
	}
	var node *modNode
	if first == "crate" {
		node = c.root
	} else {
		node = c.byFile[path]
		if node == nil {
			return "", errModChain
		}
		if first == "super" {
			node = node.parent
			if node == nil {
				return "", errModChain
			}
		}
	}
	// walk the chain, excluding the last segment (the imported name)
	for _, seg := range segs[1 : len(segs)-1] {
		switch seg {
		case "self":
			continue
		case "super":
			node = node.parent
			if node == nil {
				return "", errModChain
			}
		default:
			child, ok := node.children[seg]
			if !ok {
				return "", errModChain
			}
			node = child
		}
	}
	return node.file, nil
}

func (l *Language) ParseFile(path string) (*language.FileInfo, error) {
	c := l.getCrate(filepath.Dir(path))
	if c == nil {
		// mimic the original behaviour, which crashes when no Cargo.toml is found.
		var nilCrate *crate
		_ = nilCrate.dir
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	info := &language.FileInfo{AbsPath: path, Loc: utils.CountLines(content)}
	stmts, err := l.statements(path)
	if err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	add := func(p string) {
		if p == "" || p == path || seen[p] {
			return
		}
		seen[p] = true
		info.Deps = append(info.Deps, p)
	}
	for _, s := range stmts {
		if s.Mod != "" {
			resolved := resolveMod(path, s.Mod)
			if resolved == "" {
				info.Errors = append(info.Errors, fmt.Errorf("could not find mod %s while looking in dir %s", s.Mod, filepath.Dir(path)))
				continue
			}
			add(resolved)
			continue
		}
		resolved, err := l.resolveUse(c, path, s.Use)
		if err != nil {
			name := s.Use[len(s.Use)-1]
			if name == "*" {
				name = ""
			}
			info.Errors = append(info.Errors, fmt.Errorf("error resolving use statement for name %s: %w", name, err))
			continue
		}
		add(resolved)
	}
	return info, nil
}
EOF
echo ok"}

