	if first == "crate" {
		node = c.root
	} else {
		node = c.byFile[path]
		if node == nil {
			return "", errModChain
		}
		if first == "super" {
			node = node.parent
			if node == nil {
				return "", errModChain
			}
		}
	}
	// walk the chain, excluding the last segment (the imported name)
	for _, seg := range segs[1 : len(segs)-1] {
		switch seg {
		case "self":
			continue
		case "super":
			node = node.parent
			if node == nil {
				return "", errModChain
			}
		default:
			child, ok := node.children[seg]
			if !ok {
				return "", errModChain
			}
			node = child
		}
	}
	return node.file, nil
}

func (l *Language) ParseFile(path string) (*language.FileInfo, error) {
	c := l.getCrate(filepath.Dir(path))
	if c == nil {
		// mimic the original behaviour, which crashes when no Cargo.toml is found.
		var nilCrate *crate
		_ = nilCrate.dir
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	info := &language.FileInfo{AbsPath: path, Loc: utils.CountLines(content)}
	stmts, err := l.statements(path)
	if err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	add := func(p string) {
		if p == "" || p == path || seen[p] {
			return
		}
		seen[p] = true
		info.Deps = append(info.Deps, p)
	}
	for _, s := range stmts {
		if s.Mod != "" {
			resolved := resolveMod(path, s.Mod)
			if resolved == "" {
				info.Errors = append(info.Errors, fmt.Errorf("could not find mod %s while looking in dir %s", s.Mod, filepath.Dir(path)))
				continue
			}
			add(resolved)
			continue
		}
		resolved, err := l.resolveUse(c, path, s.Use)
		if err != nil {
			name := s.Use[len(s.Use)-1]
			if name == "*" {
				name = ""
			}
			info.Errors = append(info.Errors, fmt.Errorf("error resolving use statement for name %s: %w", name, err))
			continue
		}
		add(resolved)
	}
	return info, nil
}
