		j := skipNewlines(i)
		if isIdent(j, "import") {
			j++
			if isPunct(j, "(") {
				j++
				for {
					j = skipNewlines(j)
					if isPunct(j, ")") {
						j++
						break
					}
					next, ok := parseImportSpec(j)
					if !ok {
						break
					}
					j = next
				}
			} else {
				j, _ = parseImportSpec(j)
			}
			i = j
			continue
		}
		break
	}
	// body: collect selectors, identifiers and top level symbols.
	depth := 0
	parenDepth := 0
	for k := i; k < n; k++ {
		t := toks[k]
		if t.kind == tkPunct {
			switch t.text {
			case "{":
				depth++
			case "}":
				if depth > 0 {
					depth--
				}
			case "(":
				parenDepth++
			case ")":
				if parenDepth > 0 {
					parenDepth--
				}
			}
			continue
		}
		if t.kind != tkIdent {
			continue
		}
		if k+2 < n && isPunct(k+1, ".") && toks[k+2].kind == tkIdent {
			f.Selectors = append(f.Selectors, [2]string{t.text, toks[k+2].text})
		}
		if !(k > 0 && isPunct(k-1, ".")) {
			f.Idents = append(f.Idents, t.text)
		}
