			switch t.text {
			case "func":
				j := k + 1
				if isPunct(j, "(") {
					// method: skip receiver
					d := 0
					for j < n {
						if isPunct(j, "(") {
							d++
						} else if isPunct(j, ")") {
							d--
							if d == 0 {
								j++
								break
							}
						}
						j++
					}
					// methods are not package level symbols
					continue
				}
