cat > internal/golang/language.go <<'EOF'
package golang

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"dep-tree/internal/language"
	"dep-tree/internal/utils"
)

var Extensions = []string{"go"}

type Language struct {
	Root       string
	ModulePath string
	fileCache  map[string]*goFile
	locCache   map[string]int
}

// NewLanguage creates the Go language from the given entrypoint.
func NewLanguage(entrypoint string) (*Language, error) {
	dir := utils.FindClosestDirWithFile(filepath.Dir(entrypoint), "go.mod")
	if dir == "" {
		return nil, fmt.Errorf("no go.mod file found in any parent directory of %s", entrypoint)
	}
	modulePath := ""
	f, err := os.Open(filepath.Join(dir, "go.mod"))
	if err != nil {
		return nil, err
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "module ") {
			modulePath = strings.TrimSpace(strings.TrimPrefix(line, "module "))
			modulePath = strings.Trim(modulePath, "\"")
			break
		}
	}
	return &Language{
		Root:       dir,
		ModulePath: modulePath,
		fileCache:  map[string]*goFile{},
		locCache:   map[string]int{},
	}, nil
}

func (l *Language) parse(path string) (*goFile, error) {
	if f, ok := l.fileCache[path]; ok {
		return f, nil
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	f := parseFile(lex([]rune(string(content))))
	l.fileCache[path] = f
	l.locCache[path] = utils.CountLines(content)
	return f, nil
}

func (l *Language) Display(path string) language.DisplayResult {
	rel, err := filepath.Rel(l.Root, path)
	if err != nil {
		rel = ""
	}
	group := ""
	if f, err := l.parse(path); err == nil {
		group = f.Package
	}
	return language.DisplayResult{Name: rel, Group: group}
}

type pkgFile struct {
	path string
	file *goFile
}

func (l *Language) readPackage(dir string) ([]pkgFile, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		names = append(names, e.Name())
	}
	sort.Strings(names)
	var result []pkgFile
	for _, name := range names {
		p := filepath.Join(dir, name)
		f, err := l.parse(p)
		if err != nil {
			continue
		}
		result = append(result, pkgFile{path: p, file: f})
	}
	return result, nil
}

func (f *goFile) declares(sym string) bool {
	for _, s := range f.Symbols {
		if s == sym {
			return true
		}
	}
	return false
}

func (l *Language) ParseFile(path string) (*language.FileInfo, error) {
	f, err := l.parse(path)
	if err != nil {
		return nil, err
	}
	info := &language.FileInfo{AbsPath: path, Loc: l.locCache[path]}
	seen := map[string]bool{}
	add := func(p string) {
		if p == "" || p == path || seen[p] {
			return
		}
		seen[p] = true
		info.Deps = append(info.Deps, p)
	}
	type resolvedImport struct {
		imp   goImport
		files []pkgFile
	}
	var imports []resolvedImport
	for _, imp := range f.Imports {
		if l.ModulePath == "" || !strings.HasPrefix(imp.Path, l.ModulePath+"/") {
			continue
		}
		rel := strings.TrimPrefix(imp.Path, l.ModulePath+"/")
		dir := filepath.Join(l.Root, rel)
		files, err := l.readPackage(dir)
		if err != nil {
			info.Errors = append(info.Errors, err)
			continue
		}
		imports = append(imports, resolvedImport{imp: imp, files: files})
	}
	// selectors
	for _, sel := range f.Selectors {
		prefix, sym := sel[0], sel[1]
		for _, ri := range imports {
			if ri.imp.Alias == "." || ri.imp.Alias == "_" {
				continue
			}
			for _, pf := range ri.files {
				matches := false
				if ri.imp.Alias != "" {
					matches = ri.imp.Alias == prefix
				} else {
					matches = pf.file.Package == prefix
				}
				if matches && pf.file.declares(sym) {
					add(pf.path)
				}
			}
		}
	}
	// dot imports
	for _, ri := range imports {
		if ri.imp.Alias != "." {
			continue
		}
		for _, id := range f.Idents {
			for _, pf := range ri.files {
				if pf.file.declares(id) {
					add(pf.path)
				}
			}
		}
	}
	return info, nil
}
EOF
echo ok"}

