				if isPunct(j, "(") {
					// grouped declaration
					j++
					for j < n && !isPunct(j, ")") {
						j = skipNewlines(j)
						if isPunct(j, ")") {
							break
						}
						// names at the start of the line
						if j < n && toks[j].kind == tkIdent {
							addSymbol(toks[j].text)
							j++
							for isPunct(j, ",") && j+1 < n && toks[j+1].kind == tkIdent {
								addSymbol(toks[j+1].text)
								j += 2
							}
						}
						// skip to end of line, tracking nesting
						d := 0
						for j < n {
							if toks[j].kind == tkNewline && d == 0 {
								break
							}
							if toks[j].kind == tkPunct {
								switch toks[j].text {
								case "(", "{", "[":
									d++
								case ")", "}", "]":
									if d == 0 && toks[j].text == ")" {
										goto endGroup
									}
									d--
								}
							}
							j++
						}
					}
				endGroup:
					continue
				}
				if j < n && toks[j].kind == tkIdent {
					addSymbol(toks[j].text)
					j++
					for isPunct(j, ",") && j+1 < n && toks[j+1].kind == tkIdent {
						addSymbol(toks[j+1].text)
						j += 2
					}
				}
			}
		}
	}
	return f
}
