	Order []string
	// Entrypoints are the absolute paths of the entrypoints that were loaded.
	Entrypoints []string
}

func NewGraph() *Graph {
	return &Graph{nodes: map[string]*Node{}}
}

func (g *Graph) Get(id string) *Node {
	return g.nodes[id]
}

func (g *Graph) Has(id string) bool {
	_, ok := g.nodes[id]
	return ok
}

func (g *Graph) Nodes() []*Node {
	result := make([]*Node, 0, len(g.Order))
	for _, id := range g.Order {
		result = append(result, g.nodes[id])
	}
	return result
}

func (g *Graph) AddNode(n *Node) {
	if _, ok := g.nodes[n.Id]; !ok {
		g.Order = append(g.Order, n.Id)
	}
	g.nodes[n.Id] = n
}

// Filter decides whether a file should be part of the graph. It returns
// (ignored, explicit).
type Filter func(abs string) (bool, bool)

// Load loads the graph starting from the entrypoints following the dependencies
// of every file. If followDeps is false, only the provided files are loaded.
func (g *Graph) Load(entrypoints []string, lang language.Language, filter Filter, followDeps bool, progress *utils.Progress) error {
	visited := map[string]bool{}
	var queue []string
	for _, e := range entrypoints {
		if visited[e] {
			continue
		}
		visited[e] = true
		queue = append(queue, e)
	}
	done := 0
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if ignored, _ := filter(current); ignored {
			continue
		}
		if progress != nil {
			progress.Add(1)
		}
		done++
		info, err := lang.ParseFile(current)
		if err != nil {
			return err
		}
		node := &Node{Id: current, Errors: info.Errors, Loc: info.Loc}
		for _, dep := range info.Deps {
			if dep == current {
				continue
			}
			if ignored, _ := filter(dep); ignored {
				continue
			}
			node.Deps = append(node.Deps, dep)
			if followDeps && !visited[dep] {
				visited[dep] = true
				queue = append(queue, dep)
			}
		}
		g.AddNode(node)
		if progress != nil {
			progress.Describe(describe(done, len(visited), false))
		}
	}
	if progress != nil {
		progress.Describe(describe(done, len(visited), true))
		progress.Finish()
	}
	return nil
}

func describe(done, total int, finished bool) string {
	if finished {
		return "(" + itoa(done) + "/" + itoa(total) + ") Finished loading"
	}
	return "(" + itoa(done) + "/" + itoa(total) + ") Loading Files..."
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}

// Cycle is a list of node ids that form a cycle (the first and last are the same).
type Cycle []string

// Pruned holds the graph edges after removing the edges that cause cycles.
type Pruned struct {
	// Deps are the remaining dependencies of each node.
	Deps map[string][]string
	// Cycles found, in order of detection.
	Cycles []Cycle
	// Removed edges in order of detection.
	Removed [][2]string
}

// RemoveCycles performs a depth first traversal from the given roots and removes
// the back edges that cause cycles.
func (g *Graph) RemoveCycles(roots []string) *Pruned {
	pruned := &Pruned{Deps: map[string][]string{}}
	done := map[string]bool{}
	onStack := map[string]bool{}
	var stack []string
	var visit func(id string)
	visit = func(id string) {
		if done[id] {
			return
		}
		node := g.nodes[id]
		if node == nil {
			done[id] = true
			return
		}
		onStack[id] = true
		stack = append(stack, id)
		var deps []string
		for _, dep := range node.Deps {
			if onStack[dep] {
				idx := 0
				for i, s := range stack {
					if s == dep {
						idx = i
						break
					}
				}
				cycle := append(Cycle{}, stack[idx:]...)
				cycle = append(cycle, dep)
				pruned.Cycles = append(pruned.Cycles, cycle)
				pruned.Removed = append(pruned.Removed, [2]string{id, dep})
				continue
			}
			deps = append(deps, dep)
		}
		pruned.Deps[id] = deps
		for _, dep := range deps {
			if !done[dep] {
				visit(dep)
			}
		}
		stack = stack[:len(stack)-1]
		onStack[id] = false
		done[id] = true
	}
	for _, r := range roots {
		visit(r)
	}
	// nodes never visited keep all their deps
	for _, id := range g.Order {
		if _, ok := pruned.Deps[id]; !ok {
			pruned.Deps[id] = append([]string{}, g.nodes[id].Deps...)
		}
	}
	return pruned
}
