package language

import (
	"errors"
	"path/filepath"
	"strings"
)

// Kind identifies a supported language.
type Kind int

const (
	KindUnknown Kind = iota
	KindJs
	KindPython
	KindRust
	KindGo
)

var ErrUnsupported = errors.New("none of the provided files belong to the a supported language")

var extensions = map[Kind][]string{
	KindJs:     {"js", "jsx", "ts", "tsx", "mjs", "cjs", "mts", "cts"},
	KindPython: {"py", "pyi"},
	KindRust:   {"rs"},
	KindGo:     {"go"},
}

// KindOf returns the language kind of a file based on its extension.
func KindOf(path string) Kind {
	ext := strings.TrimPrefix(filepath.Ext(path), ".")
	for kind, exts := range extensions {
		for _, e := range exts {
			if e == ext {
				return kind
			}
		}
	}
	return KindUnknown
}

// InferKind returns the kind of the first file with a supported language, and
// that file.
func InferKind(files []string) (Kind, string, error) {
	for _, f := range files {
		if k := KindOf(f); k != KindUnknown {
			return k, f, nil
		}
	}
	return KindUnknown, "", ErrUnsupported
}
