// inferLanguage creates the language from the given entrypoints.
func inferLanguage(files []string) (language.Language, error) {
	kind, first, err := language.InferKind(files)
	if err != nil {
		return nil, err
	}
	switch kind {
	case language.KindJs:
		return js.NewLanguage(), nil
	case language.KindPython:
		return python.NewLanguage(), nil
	case language.KindRust:
		return rust.NewLanguage(), nil
	case language.KindGo:
		return golang.NewLanguage(first)
	}
	return nil, language.ErrUnsupported
}
