package entropy

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"hash/fnv"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"

	"dep-tree/internal/graph"
	"dep-tree/internal/language"
	"dep-tree/internal/utils"
)

//go:embed template_head.bin
var templateHead []byte

//go:embed template_tail.bin
var templateTail []byte

type RenderConfig struct {
	NoBrowserOpen bool
	EnableGui     bool
	RenderPath    string
}

type Node struct {
	Id           int      `json:"id"`
	IsEntrypoint bool     `json:"isEntrypoint"`
	FileName     string   `json:"fileName"`
	PathBuf      []string `json:"pathBuf"`
	Group        string   `json:"group,omitempty"`
	DirName      string   `json:"dirName"`
	Loc          int      `json:"loc"`
	Size         int      `json:"size"`
}

type Link struct {
	From     int  `json:"from"`
	To       int  `json:"to"`
	IsCyclic bool `json:"isCyclic"`
}

type Data struct {
	Nodes     []Node `json:"nodes"`
	Links     []Link `json:"links"`
	EnableGui bool   `json:"enableGui"`
}

func hashId(s string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(s))
	return int(h.Sum32())
}

func BuildData(g *graph.Graph, lang language.Language, enableGui bool) Data {
	data := Data{Nodes: []Node{}, Links: []Link{}, EnableGui: enableGui}
	pruned := g.RemoveCycles(g.Entrypoints)
	maxLoc := 0
	for _, n := range g.Nodes() {
		if n.Loc > maxLoc {
			maxLoc = n.Loc
		}
	}
	for _, n := range g.Nodes() {
		display := lang.Display(n.Id)
		dirName := filepath.Dir(display.Name)
		size := 0
		if maxLoc > 0 {
			size = n.Loc * 10 / maxLoc
		}
		data.Nodes = append(data.Nodes, Node{
			Id:           hashId(n.Id),
			IsEntrypoint: len(g.Entrypoints) == 1 && g.Entrypoints[0] == n.Id,
			FileName:     filepath.Base(display.Name),
			PathBuf:      utils.SplitPath(n.Id),
			Group:        display.Group,
			DirName:      dirName + string(filepath.Separator),
			Loc:          n.Loc,
			Size:         size,
		})
	}
	for _, n := range g.Nodes() {
		for _, dep := range pruned.Deps[n.Id] {
			data.Links = append(data.Links, Link{From: hashId(n.Id), To: hashId(dep)})
		}
	}
	for _, edge := range pruned.Removed {
		data.Links = append(data.Links, Link{From: hashId(edge[0]), To: hashId(edge[1]), IsCyclic: true})
	}
	return data
}

func Render(g *graph.Graph, lang language.Language, cfg RenderConfig) error {
	data := BuildData(g, lang, cfg.EnableGui)
	marshaled, err := json.Marshal(data)
	if err != nil {
		return err
	}
	content := make([]byte, 0, len(templateHead)+len(marshaled)+len(templateTail))
	content = append(content, templateHead...)
	content = append(content, marshaled...)
	content = append(content, templateTail...)

	renderPath := cfg.RenderPath
	if renderPath == "" {
		renderPath = filepath.Join(os.TempDir(), "index.html")
	}
	if err := os.WriteFile(renderPath, content, 0600); err != nil {
		return err
	}
	fmt.Println(renderPath)
	if cfg.NoBrowserOpen {
		return nil
	}
	return openBrowser(renderPath)
}

func openBrowser(path string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", path)
	case "windows":
		cmd = exec.Command("rundll32", "url.dll,FileProtocolHandler", path)
	default:
		cmd = exec.Command("xdg-open", path)
	}
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}
EOF
