package tree

import (
	"sort"

	"dep-tree/internal/graph"
	"dep-tree/internal/language"
)

// Tree is a dependency tree rooted at a single node.
type Tree struct {
	Root   string
	Graph  *graph.Graph
	Lang   language.Language
	Pruned *graph.Pruned
	// Nodes reachable from the root, sorted by level and id.
	Nodes  []*TreeNode
	byId   map[string]*TreeNode
	// BackEdges are the removed edges (src, dst) in detection order.
	BackEdges [][2]string
}

type TreeNode struct {
	Id       string
	Name     string
	Level    int
	Children []string
	Errors   []error
}

func NewTree(root string, g *graph.Graph, lang language.Language) *Tree {
	pruned := g.RemoveCycles([]string{root})
	t := &Tree{Root: root, Graph: g, Lang: lang, Pruned: pruned, byId: map[string]*TreeNode{}}
	// compute levels as the longest path from the root.
	levels := map[string]int{root: 0}
	order := []string{}
	visited := map[string]bool{}
	var topo func(id string)
	topo = func(id string) {
		if visited[id] {
			return
		}
		visited[id] = true
		for _, dep := range pruned.Deps[id] {
			topo(dep)
		}
		order = append(order, id)
	}
	topo(root)
	// order is reverse topological; process from the root downwards.
	for i := len(order) - 1; i >= 0; i-- {
		id := order[i]
		lvl := levels[id]
		for _, dep := range pruned.Deps[id] {
			if levels[dep] < lvl+1 {
				levels[dep] = lvl + 1
			}
		}
	}
	for id, lvl := range levels {
		n := g.Get(id)
		tn := &TreeNode{Id: id, Name: lang.Display(id).Name, Level: lvl, Children: pruned.Deps[id]}
		if n != nil {
			tn.Errors = n.Errors
		}
		t.Nodes = append(t.Nodes, tn)
		t.byId[id] = tn
	}
	sort.Slice(t.Nodes, func(i, j int) bool {
		if t.Nodes[i].Level != t.Nodes[j].Level {
			return t.Nodes[i].Level < t.Nodes[j].Level
		}
		return t.Nodes[i].Id < t.Nodes[j].Id
	})
	for _, edge := range pruned.Removed {
		if _, ok := levels[edge[0]]; ok {
			if _, ok := levels[edge[1]]; ok {
				t.BackEdges = append(t.BackEdges, edge)
			}
		}
	}
	return t
}

func (t *Tree) Node(id string) *TreeNode {
	return t.byId[id]
}
