package tree

import (
	"encoding/json"
)

type jsonTree map[string]interface{}

func (t *Tree) jsonNode(id string, visiting map[string]bool) interface{} {
	deps := t.Pruned.Deps[id]
	if len(deps) == 0 {
		return nil
	}
	result := jsonTree{}
	for _, dep := range deps {
		if visiting[dep] {
			continue
		}
		visiting[dep] = true
		result[t.Lang.Display(dep).Name] = t.jsonNode(dep, visiting)
		delete(visiting, dep)
	}
	if len(result) == 0 {
		return nil
	}
	return result
}

// RenderJSON renders the tree in a machine readable format.
func (t *Tree) RenderJSON() (string, error) {
	tree := jsonTree{}
	tree[t.Lang.Display(t.Root).Name] = t.jsonNode(t.Root, map[string]bool{t.Root: true})
	cycles := [][]string{}
	for _, c := range t.Pruned.Cycles {
		var names []string
		for _, id := range c {
			names = append(names, t.Lang.Display(id).Name)
		}
		cycles = append(cycles, names)
	}
	errs := map[string][]string{}
	for _, n := range t.Graph.Nodes() {
		if len(n.Errors) == 0 {
			continue
		}
		name := t.Lang.Display(n.Id).Name
		for _, e := range n.Errors {
			errs[name] = append(errs[name], e.Error())
		}
	}
	output := struct {
		Tree                 jsonTree            `json:"tree"`
		CircularDependencies [][]string          `json:"circularDependencies"`
		Errors               map[string][]string `json:"errors"`
	}{tree, cycles, errs}
	marshaled, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		return "", err
	}
	return string(marshaled), nil
}
