package tree

import (
	"unicode/utf8"
)

// Placement of a node in the board.
type Placement struct {
	Node *TreeNode
	Row  int
	X    int
	// Width is the rune width of the name.
	Width int
}

type cellKey struct{ row, col int }

type cell struct {
	ch rune
	// text marks cells that belong to node names.
	text bool
}

// Board is the rendered layout of a tree.
type Board struct {
	Tree       *Tree
	Placements []*Placement
	byId       map[string]*Placement
	byRow      map[int]*Placement
	cells      map[cellKey]*cell
	Rows       int
	Cols       int
}

func (b *Board) get(row, col int) rune {
	if c, ok := b.cells[cellKey{row, col}]; ok {
		return c.ch
	}
	return 0
}

func (b *Board) set(row, col int, ch rune) {
	b.cells[cellKey{row, col}] = &cell{ch: ch}
	if row+1 > b.Rows {
		b.Rows = row + 1
	}
	if col+1 > b.Cols {
		b.Cols = col + 1
	}
}

func (b *Board) setText(row, col int, ch rune) {
	b.cells[cellKey{row, col}] = &cell{ch: ch, text: true}
	if row+1 > b.Rows {
		b.Rows = row + 1
	}
	if col+1 > b.Cols {
		b.Cols = col + 1
	}
}

func (b *Board) PlacementAtRow(row int) *Placement {
	return b.byRow[row]
}

func (b *Board) Placement(id string) *Placement {
	return b.byId[id]
}

// busEnd returns the last row of the bus of the given placement, or -1 if it
// has no children.
func (b *Board) busEnd(p *Placement) int {
	last := -1
	for _, c := range p.Node.Children {
		if cp, ok := b.byId[c]; ok && cp.Row > last {
			last = cp.Row
		}
	}
	return last
}

// arrowCol returns the column of the incoming arrow of a placement.
func arrowCol(p *Placement) int {
	if p.Width == 0 {
		return p.X
	}
	return p.X - 1
}

func NewBoard(t *Tree) *Board {
	b := &Board{
		Tree:  t,
		byId:  map[string]*Placement{},
		byRow: map[int]*Placement{},
		cells: map[cellKey]*cell{},
	}
	// rows
	for i, n := range t.Nodes {
		p := &Placement{Node: n, Row: i + n.Level, Width: utf8.RuneCountInString(n.Name)}
		b.Placements = append(b.Placements, p)
		b.byId[n.Id] = p
		b.byRow[p.Row] = p
	}
	// columns
	maxXByLevel := map[int]int{}
	for _, p := range b.Placements {
		if p.Node.Level == 0 {
			p.X = 0
		} else {
			p.X = maxXByLevel[p.Node.Level-1] + 2
			// push the node right while the cell is occupied by a bus of a
			// previously placed node.
			for b.busOccupies(p.Row, p.X, p) {
				p.X++
			}
		}
		if p.X > maxXByLevel[p.Node.Level] {
			maxXByLevel[p.Node.Level] = p.X
		}
	}
	b.draw()
	return b
}

// busOccupies checks whether the bus of any node placed before `until` passes
// through the given cell.
func (b *Board) busOccupies(row, col int, until *Placement) bool {
	for _, p := range b.Placements {
		if p == until {
			return false
		}
		if p.X != col {
			continue
		}
		end := b.busEnd(p)
		if row > p.Row && row <= end {
			return true
		}
	}
	return false
}

func (b *Board) draw() {
	// horizontals
	for _, p := range b.Placements {
		for _, c := range p.Node.Children {
			cp, ok := b.byId[c]
			if !ok {
				continue
			}
			arrow := arrowCol(cp)
			for col := p.X + 1; col < arrow; col++ {
				b.set(cp.Row, col, '─')
			}
			b.set(cp.Row, arrow, '▷')
		}
	}
	// buses
	for _, p := range b.Placements {
		end := b.busEnd(p)
		if end < 0 {
			continue
		}
		if b.get(p.Row, p.X) == 0 {
			b.set(p.Row, p.X, '╷')
		}
		childRows := map[int]bool{}
		for _, c := range p.Node.Children {
			if cp, ok := b.byId[c]; ok {
				childRows[cp.Row] = true
			}
		}
		for row := p.Row + 1; row <= end; row++ {
			if childRows[row] {
				var ch rune
				if row == end {
					ch = '└'
					if b.get(row, p.X-1) == '─' {
						ch = '┴'
					}
				} else {
					ch = '├'
					if b.get(row, p.X-1) == '─' {
						ch = '┼'
					}
				}
				b.set(row, p.X, ch)
			} else {
				b.set(row, p.X, '│')
			}
		}
	}
	// back edges
	for _, edge := range b.Tree.BackEdges {
		b.drawBackEdge(edge[0], edge[1], func(row, col int, ch rune) {
			b.mergeLine(row, col, ch)
		}, func(row, col int, ch rune) {
			if b.get(row, col) == 0 {
				b.set(row, col, ch)
			}
		})
	}
	// text
	for _, p := range b.Placements {
		col := p.X
		for _, r := range p.Node.Name {
			b.setText(p.Row, col, r)
			col++
		}
	}
}

// BackEdgeColumn computes the column where the vertical part of a back edge is drawn.
func (b *Board) BackEdgeColumn(src, dst *Placement) int {
	maxEnd := 0
	for row := dst.Row; row <= src.Row; row++ {
		if p, ok := b.byRow[row]; ok {
			if end := p.X + p.Width; end > maxEnd {
				maxEnd = end
			}
		}
	}
	return maxEnd + 1
}

// drawBackEdge traces a back edge from src to dst. The line callback is used for
// the line characters and the arrow callback for the arrow head.
func (b *Board) drawBackEdge(srcId, dstId string, line func(row, col int, ch rune), arrow func(row, col int, ch rune)) {
	src, ok1 := b.byId[srcId]
	dst, ok2 := b.byId[dstId]
	if !ok1 || !ok2 {
		return
	}
	col := b.BackEdgeColumn(src, dst)
	arrow(dst.Row, dst.X+dst.Width, '◁')
	for c := dst.X + dst.Width + 1; c < col; c++ {
		line(dst.Row, c, '─')
	}
	line(dst.Row, col, '┐')
	for row := dst.Row + 1; row < src.Row; row++ {
		line(row, col, '│')
	}
	for c := src.X + src.Width; c < col; c++ {
		line(src.Row, c, '─')
	}
	line(src.Row, col, '┘')
}

// direction flags for box drawing merging
const (
	dirUp = 1 << iota
	dirDown
	dirLeft
	dirRight
)

var runeDirs = map[rune]int{
	'│': dirUp | dirDown,
	'─': dirLeft | dirRight,
	'┐': dirDown | dirLeft,
	'┘': dirUp | dirLeft,
	'┌': dirDown | dirRight,
	'└': dirUp | dirRight,
	'├': dirUp | dirDown | dirRight,
	'┤': dirUp | dirDown | dirLeft,
	'┬': dirDown | dirLeft | dirRight,
	'┴': dirUp | dirLeft | dirRight,
	'┼': dirUp | dirDown | dirLeft | dirRight,
	'╷': dirDown,
	'╵': dirUp,
	'╶': dirRight,
	'╴': dirLeft,
}

var dirsRune = func() map[int]rune {
	m := map[int]rune{}
	for r, d := range runeDirs {
		m[d] = r
	}
	return m
}()

// mergeLine draws a line character merging it with the existing one.
func (b *Board) mergeLine(row, col int, ch rune) {
	existing := b.get(row, col)
	if existing == 0 {
		b.set(row, col, ch)
		return
	}
	if c, ok := b.cells[cellKey{row, col}]; ok && c.text {
		b.set(row, col, ch)
		return
	}
	ed, ok1 := runeDirs[existing]
	nd, ok2 := runeDirs[ch]
	if !ok1 || !ok2 {
		b.set(row, col, ch)
		return
	}
	if r, ok := dirsRune[ed|nd]; ok {
		b.set(row, col, r)
		return
	}
	b.set(row, col, ch)
}
EOF
echo ok"}

