	for _, edge := range b.Tree.BackEdges {
		if edge[0] != p.Node.Id {
			continue
		}
		b.drawBackEdge(edge[0], edge[1], func(row, col int, ch rune) {
			put(row, col, ch, styleSelected)
		}, func(row, col int, ch rune) {
			put(row, col, ch, styleSelected)
		})
	}
	// names
	for _, c := range p.Node.Children {
		if cp, ok := b.byId[c]; ok {
			col := cp.X
			for _, r := range cp.Node.Name {
				put(cp.Row, col, r, styleDep)
				col++
			}
		}
	}
	style := styleSelected
	if len(p.Node.Errors) > 0 {
		style = styleSelErr
	}
	col := p.X
	for _, r := range p.Node.Name {
		put(p.Row, col, r, style)
		col++
	}
	// errors panel
	if len(p.Node.Errors) > 0 {
		x0 := w - 40
		if x0 < 40 {
			x0 = 40
		}
		row := 0
		for _, err := range p.Node.Errors {
			row = drawWrapped(s, x0, w, row, "- "+err.Error(), styleError)
		}
	}
}

// drawWrapped draws text word by word wrapping at the right edge, returning the
// next free row.
func drawWrapped(s tcell.Screen, x0, x2, row int, text string, style tcell.Style) int {
	col := x0
	words := strings.Split(text, " ")
	for _, word := range words {
		runes := []rune(word)
		if col > x0 && col+len(runes) > x2-2 {
			row++
			col = x0
		}
		for _, r := range runes {
			if col >= x2 {
				row++
				col = x0
			}
			s.SetContent(col, row, r, nil, style)
			col++
		}
		if col < x2 {
			s.SetContent(col, row, ' ', nil, style)
			col++
		}
	}
	return row + 1
}
