package check

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"dep-tree/internal/graph"
	"dep-tree/internal/language"
	"dep-tree/internal/utils"
)

type violation struct {
	from   string
	to     string
	reason string
}

func (c *Config) rel(abs string) string {
	rel, err := filepath.Rel(c.Path, abs)
	if err != nil {
		return abs
	}
	return rel
}

func (c *Config) matches(pattern, rel string) bool {
	return utils.GlobMatch(pattern, rel)
}

// Check validates the dependency rules against the loaded graph.
func Check(c *Config, g *graph.Graph, lang language.Language) error {
	var order []string
	seen := map[string]bool{}
	reasons := map[string]string{}
	addViolation := func(from, to, reason string) {
		key := from + " -> " + to
		if !seen[key] {
			seen[key] = true
			order = append(order, key)
		}
		reasons[key] = reason
	}
	for _, n := range g.Nodes() {
		from := c.rel(n.Id)
		for _, dep := range n.Deps {
			to := c.rel(dep)
			// white list
			for pattern, entry := range c.WhiteList {
				if !c.matches(pattern, from) {
					continue
				}
				allowed := false
				for _, p := range c.expand(entry.To) {
					if c.matches(p, to) {
						allowed = true
						break
					}
				}
				if !allowed {
					addViolation(from, to, entry.Reason)
				}
			}
			// black list
			for pattern, entries := range c.BlackList {
				if !c.matches(pattern, from) {
					continue
				}
				for _, entry := range entries {
					for _, p := range c.expand([]string{entry.To}) {
						if c.matches(p, to) {
							addViolation(from, to, entry.Reason)
						}
					}
				}
			}
		}
	}
	var cycles []graph.Cycle
	if !c.AllowCircularDependencies {
		pruned := g.RemoveCycles(g.Entrypoints)
		cycles = pruned.Cycles
	}
	if len(order) == 0 && len(cycles) == 0 {
		return nil
	}
	var sb strings.Builder
	sb.WriteString("Check failed, the following dependencies are not allowed:\n")
	for _, key := range order {
		sb.WriteString("- " + key + "\n")
		if r := reasons[key]; r != "" {
			sb.WriteString("  " + r + "\n")
		}
	}
	if len(cycles) > 0 {
		sb.WriteString("\ndetected circular dependencies:\n")
		for _, cycle := range cycles {
			var names []string
			for _, id := range cycle {
				names = append(names, lang.Display(id).Name)
			}
			sb.WriteString("- " + strings.Join(names, " -> ") + "\n")
		}
	}
	return errors.New(sb.String())
}

// Entrypoints returns the absolute paths of the configured entrypoints.
func (c *Config) AbsEntrypoints() ([]string, error) {
	if len(c.Entrypoints) == 0 {
		return nil, fmt.Errorf("config file \"%s\" has no entrypoints", c.Path)
	}
	var result []string
	for _, e := range c.Entrypoints {
		p := e
		if !filepath.IsAbs(p) {
			p = filepath.Join(c.Path, p)
		}
		result = append(result, p)
	}
	return result, nil
}

func init() {
	_ = os.Stderr
}
