	var overlapRight bool

	cmd := &cobra.Command{
		Use:     "explain",
		Short:   "Shows all the dependencies between two parts of the code",
		GroupID: explainGroupId,
		Args:    cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if overlapLeft && overlapRight {
				return errors.New("only one of --overlap-left (-l) or --overlap-right (-r) can be used at a time")
			}
			left, err := filesFromArgs([]string{args[0]})
			if err != nil {
				return err
			}
			right, err := filesFromArgs([]string{args[1]})
			if err != nil {
				return err
			}
			cfg, err := loadConfig()
			if err != nil {
				return err
			}
			lang, err := inferLanguage(left)
			if err != nil {
				return err
			}
			leftSet := map[string]bool{}
			rightSet := map[string]bool{}
			for _, f := range left {
				leftSet[f] = true
			}
			for _, f := range right {
				rightSet[f] = true
			}
			if overlapLeft {
				for f := range leftSet {
					delete(rightSet, f)
				}
			}
			if overlapRight {
				for f := range rightSet {
					delete(leftSet, f)
				}
			}
			var all []string
			seen := map[string]bool{}
			for _, f := range append(append([]string{}, left...), right...) {
				if !seen[f] {
					seen[f] = true
					all = append(all, f)
				}
			}
			progress := utils.NewProgress()
			g := graph.NewGraph()
			if err := g.Load(all, lang, cfg.IgnoreFiles, false, progress); err != nil {
				return err
			}
